        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, approx_quantile(duration,0.95)/1e6 AS p95ms FROM abnormal_traces WHERE service_name='ts-config-service' AND span_name IN ('SELECT Config','ConfigRepository.findByName','GET /api/v1/configservice/configs/{configName}') GROUP BY ALL", "claim": "Config's DB 'SELECT Config' spans all error out at about 30s, versus about 1.5ms normally."},
        {"kind": "log", "sql": "SELECT level, message, count(*) AS n FROM abnormal_logs WHERE service_name='ts-config-service' AND (message LIKE '%Communications link failure%' OR message LIKE '%Connection is not available%' OR message LIKE '%No operations allowed after connection closed%') GROUP BY ALL ORDER BY n DESC", "claim": "Config logs show MySQL connection failures, closed connections and Hikari pool-timeout errors during the incident."},
        {"kind": "metric", "sql": "SELECT metric, avg(value) AS avg_v, max(value) AS max_v FROM abnormal_metrics_sum WHERE service_name='ts-config-service' AND metric LIKE 'db.client.connections%' GROUP BY metric ORDER BY metric", "claim": "Config's DB connection pool shows timeouts 8.5 and pending requests 5.5 with zero connections in use."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-config-service", "to": "ts-seat-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, approx_quantile(duration,0.95)/1e6 AS p95ms FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Seat service's left_tickets server spans all fail at about 60s after config's DB failures begin."}]},
    {"from": "ts-seat-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, approx_quantile(duration,0.95)/1e6 AS p95ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name LIKE '%trips/left%' GROUP BY ALL", "claim": "Travel's trips/left server spans fail, with 9 of 14 erroring and p95 near 61s."}]},
    {"from": "ts-seat-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, approx_quantile(duration,0.95)/1e6 AS p95ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Travel2's trips/left server spans fail, with 8 of 10 erroring and p95 near 60s."}]},
    {"from": "ts-travel-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, approx_quantile(duration,0.95)/1e6 AS p95ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Route-plan cheapestRoute and quickestRoute server spans all fail at about 60s."}]},
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, approx_quantile(duration,0.95)/1e6 AS p95ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Route-plan server spans fail at about 60s, consistent with calls to the failing travel2 service."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, approx_quantile(duration,0.95)/1e6 AS p95ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY ALL", "claim": "Travel-plan travelPlan cheapest and quickest server spans all fail at about 60s."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs, approx_quantile(duration,0.95)/1e6 AS p95ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY ALL", "claim": "UI dashboard travel-plan and trips requests reach 20s p95 in the abnormal window, against normal latency."}]}
